func Test_redhatBase_parseInstalledPackages_continuesAfterNonStandardSourceRPM(t *testing.T) {
	o := &redhatBase{base: base{
		Distro: config.Distro{Family: constant.Alma, Release: "9.0"},
		log:    logging.NewIODiscardLogger(),
	}}
	gotbps, gotsps, err := o.parseInstalledPackages(`elasticsearch 0 8.17.0 1 x86_64 elasticsearch-8.17.0-1-src.rpm (none)
bar 1 9 123a ia64 1:bar-9-123a.src.rpm`)
	if err != nil {
		t.Fatalf("parseInstalledPackages() error = %v", err)
	}
	wantbps := models.Packages{
		"elasticsearch": {Name: "elasticsearch", Version: "8.17.0", Release: "1", Arch: "x86_64"},
