					Arch:        "src",
					BinaryNames: []string{fields[0]},
				}, nil
			}
		}()
		if err != nil {
			o.warns = append(o.warns, xerrors.Errorf("Failed to parse sourcepkg. err: %w", err))
		}

		return &models.Package{
			Name: fields[0],
			Version: func() string {
				switch fields[1] {
				case "0", "(none)":
					return fields[2]
				default:
					return fmt.Sprintf("%s:%s", fields[1], fields[2])
				}
			}(),
			Release: fields[3],
			Arch:    fields[4],
			ModularityLabel: func() string {
				if len(fields) == 7 && fields[6] != "(none)" {
					return fields[6]
				}
				return ""
			}(),
		}, sp, nil
	default:
		return nil, nil, xerrors.Errorf("Failed to parse package line: %s", line)
	}
}

